async function controlProjects(request: ProjectsControlRequest): Promise<void> {
    try {
      await requestProjectsControl(context, connection.current, request)
    } catch (error) {
      context.log(`tasks: projects control failed: ${errorMessage(error)}`)
      applyControl(request)
    }
  }

export async function requestProjectsControl(context: UiPluginContext, connection: WindowConnection, request: ProjectsControlRequest): Promise<void> {
  if (connection.current === null) {
    const response = await context.call('ui.window.self', {})
    const connId = response !== null && typeof response === 'object' && !Array.isArray(response)
      ? (response as Record<string, unknown>).connId
      : undefined
    if (typeof connId !== 'number' || !Number.isSafeInteger(connId) || connId <= 0) {
      throw new Error('The daemon did not identify this window.')
    }
    connection.current = connId
  }
  const descriptor = projectsControlDescriptor(request)
  await context.call('ui.window.command.run', { connId: connection.current, id: descriptor.command, args: descriptor.args })
}

export function projectsControlDescriptor(request: ProjectsControlRequest): ProjectsControlDescriptor {
  return { command: PROJECTS_CONTROL_COMMAND, args: request }
}

async function browseProjects(force = false) {
    setPickerBusy(true)
    setBrowseLoading(true)
    setBrowseError(null)
    setBrowseErrorHost(null)
    try {
      const result = object(await context.call('quirky.tasks/projects', { ...(force ? { refresh: true } : {}) }))
      const found = (Array.isArray(result.projects) ? result.projects : []).flatMap((value) => normalizeProjectTarget(value) ? [normalizeProjectTarget(value)!] : []).slice(0, 32)
      setBrowsedProjects(found)
      setPartialFailures(Array.isArray(result.partialFailures) ? result.partialFailures.flatMap((entry) => record(entry) ? [record(entry)!] : []) : [])
      setBrowseOpen(true)
    } catch (error) {
      setBrowseError(error)
      setBrowseErrorHost(hostFromError(error))
      setBrowseOpen(true)
    } finally {
      setPickerBusy(false)
      setBrowseLoading(false)
    }
  }

